void StudioWindow::editDirection(){
 if(bridge.busy()||projectData().isEmpty())return;auto project=projectData(),visual=project.value("visual").toObject(),config=visual.value("direction").toObject();const auto revision=view.value("revision"),root=view.value("root");
 QDialog dialog(this);dialog.setObjectName("directionDialog");dialog.setWindowTitle(tr("연출 작업실 · 순차 / 동시 재생"));dialog.resize(1380,820);auto box=new QVBoxLayout(&dialog);
 auto help=new QLabel(tr("배우의 기본 이미지 위에 의상·표정을 겹칩니다. 동작은 쉼표로 구분한 이미지 프레임입니다. 같은 연출·구간의 행은 동시에 재생하고, 구간 번호 순으로 이어집니다. 좌표는 화면 기준입니다. 빈 표정·의상·동작은 기본 이미지로 돌아갑니다. 게임 규칙이나 비용은 실행하지 않습니다."));help->setWordWrap(true);box->addWidget(help);auto tabs=new QTabWidget;tabs->setObjectName("directionTabs");box->addWidget(tabs);
 auto table=[&](QString id,QString name,QStringList headers){auto page=new QWidget;auto layout=new QVBoxLayout(page);auto t=new QTableWidget(0,headers.size());t->setObjectName(id);t->setHorizontalHeaderLabels(headers);t->horizontalHeader()->setSectionResizeMode(QHeaderView::Interactive);t->setSelectionBehavior(QAbstractItemView::SelectRows);layout->addWidget(t);auto row=new QHBoxLayout;auto add=new QPushButton(tr("추가")),remove=new QPushButton(tr("선택 삭제"));add->setObjectName(id+"Add");remove->setObjectName(id+"Remove");row->addWidget(add);row->addWidget(remove);row->addStretch();layout->addLayout(row);connect(add,&QPushButton::clicked,&dialog,[t]{int r=t->rowCount();t->insertRow(r);for(int c=0;c<t->columnCount();++c)t->setItem(r,c,new QTableWidgetItem);t->setCurrentCell(r,0);});connect(remove,&QPushButton::clicked,&dialog,[t]{if(t->currentRow()>=0)t->removeRow(t->currentRow());});tabs->addTab(page,name);return t;};
 auto actors=table("directionActors",tr("배우"),{"ID","이름","기본 이미지 ID"});auto variants=table("directionVariants",tr("표정 · 의상 · 동작"),{"배우 ID","종류: expression / outfit / motion","ID","이미지 ID / 프레임 목록","프레임 ms"});auto sequences=table("directionSequences",tr("연출 연결"),{"ID","이름","버튼을 배치할 화면 ID"});auto cues=table("directionCues",tr("구간 · 동시 동작"),{"연출 ID","구간 번호","구간 이름","길이 ms","배우 ID","X","Y","너비","높이","종료 X","종료 Y","불투명도","표정 ID","의상 ID","동작 ID"});
 auto addRow=[](QTableWidget*t,const QStringList& values){int row=t->rowCount();t->insertRow(row);for(int c=0;c<t->columnCount();++c)t->setItem(row,c,new QTableWidgetItem(values.value(c)));};
 for(auto v:config.value("actors").toArray()){auto a=v.toObject();addRow(actors,{a.value("id").toString(),a.value("name").toString(),a.value("assetId").toString()});for(auto group:QStringList{"expressions","outfits","motions"})for(auto x:a.value(group).toArray()){auto o=x.toObject();QStringList frames;for(auto f:o.value("frames").toArray())frames<<f.toString();addRow(variants,{a.value("id").toString(),group=="expressions"?"expression":group=="outfits"?"outfit":"motion",o.value("id").toString(),group=="motions"?frames.join(','):o.value("assetId").toString(),group=="motions"?QString::number(o.value("frameMs").toInt()):""});}}
 for(auto v:config.value("sequences").toArray()){auto s=v.toObject();addRow(sequences,{s.value("id").toString(),s.value("name").toString(),""});int index=0;for(auto st:s.value("stages").toArray()){auto stage=st.toObject();for(auto cv:stage.value("cues").toArray()){auto c=cv.toObject();QStringList cells{s.value("id").toString(),QString::number(index),stage.value("name").toString(),QString::number(stage.value("durationMs").toInt()),c.value("actorId").toString()};for(auto key:QStringList{"x","y","width","height","toX","toY","opacity"})cells<< (c.contains(key)?QString::number(c.value(key).toDouble()):"");cells<<c.value("expressionId").toString()<<c.value("outfitId").toString()<<c.value("motionId").toString();addRow(cues,cells);}++index;}}
 auto error=new QLabel;error->setWordWrap(true);error->setObjectName("directionError");box->addWidget(error);auto buttons=new QDialogButtonBox(QDialogButtonBox::Save|QDialogButtonBox::Cancel);box->addWidget(buttons);connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);
 connect(buttons,&QDialogButtonBox::accepted,&dialog,[&]{try{
  if(root!=view.value("root")||revision!=view.value("revision"))throw QString(tr("초안이 변경되었습니다. 다시 열어 주세요."));
  auto cell=[](QTableWidget*t,int r,int c){return t->item(r,c)->text().trimmed();};auto number=[&](QTableWidget*t,int r,int c,double lo,double hi,bool integer){bool ok=false;double n=cell(t,r,c).toDouble(&ok);if(!ok||!std::isfinite(n)||n<lo||n>hi||(integer&&std::floor(n)!=n))throw QString(tr("%1행 %2열 수치 범위: %3~%4").arg(r+1).arg(c+1).arg(lo).arg(hi));return n;};
  QJsonArray as;QSet<QString> actorIds;for(int r=0;r<actors->rowCount();++r){auto id=cell(actors,r,0);if(id.isEmpty()||actorIds.contains(id))throw QString(tr("배우 ID가 비었거나 중복입니다."));actorIds.insert(id);as.append(QJsonObject{{"id",id},{"name",cell(actors,r,1)},{"assetId",cell(actors,r,2)}});}
  for(int r=0;r<variants->rowCount();++r){auto id=cell(variants,r,0),kind=cell(variants,r,1);if(!actorIds.contains(id))throw QString(tr("변형의 배우 ID가 없습니다."));QString key=kind=="expression"?"expressions":kind=="outfit"?"outfits":kind=="motion"?"motions":"";if(key.isEmpty())throw QString(tr("변형 종류는 expression / outfit / motion입니다."));QJsonObject item{{"id",cell(variants,r,2)}};if(kind=="motion"){QJsonArray frames;for(auto f:cell(variants,r,3).split(',',Qt::SkipEmptyParts))frames.append(f.trimmed());item["frames"]=frames;item["frameMs"]=number(variants,r,4,16,10000,true);}else item["assetId"]=cell(variants,r,3);for(int i=0;i<as.size();++i){auto a=as[i].toObject();if(a.value("id")==id){auto list=a.value(key).toArray();list.append(item);a[key]=list;as[i]=a;}}}
  QJsonArray ss;QSet<QString> sequenceIds;auto screens=visual.value("screens").toArray();for(int r=0;r<sequences->rowCount();++r){const auto id=cell(sequences,r,0),screenId=cell(sequences,r,2);if(id.isEmpty()||sequenceIds.contains(id))throw QString(tr("연출 ID가 비었거나 중복입니다."));sequenceIds.insert(id);QMap<int,QJsonObject> stages;
   for(int j=0;j<cues->rowCount();++j)if(cell(cues,j,0)==id){int index=number(cues,j,1,0,99,true);auto name=cell(cues,j,2);int duration=number(cues,j,3,1,60000,true);if(stages.contains(index)&&(stages[index].value("name")!=name||stages[index].value("durationMs")!=duration))throw QString(tr("동일 구간의 이름과 길이는 같아야 합니다."));QJsonObject c{{"actorId",cell(cues,j,4)}};if(!actorIds.contains(cell(cues,j,4)))throw QString(tr("구간의 배우 ID가 없습니다."));QStringList keys{"x","y","width","height","toX","toY","opacity"};for(int k=0;k<keys.size();++k){if(k>=4&&cell(cues,j,5+k).isEmpty())continue;c[keys[k]]=number(cues,j,5+k,k==6?0:(k==2||k==3?1:-4096),k==6?1:4096,false);}for(int k=0;k<3;++k)if(!cell(cues,j,12+k).isEmpty())c[QStringList{"expressionId","outfitId","motionId"}[k]]=cell(cues,j,12+k);auto list=stages[index].value("cues").toArray();for(auto v:list)if(v.toObject().value("actorId")==c.value("actorId"))throw QString(tr("동시 구간의 배우가 중복입니다."));list.append(c);stages[index]=QJsonObject{{"name",name},{"durationMs",duration},{"cues",list}};}
   if(stages.isEmpty())throw QString(tr("연출에는 하나 이상의 구간이 필요합니다."));QJsonArray list;for(auto st:stages)list.append(st);ss.append(QJsonObject{{"id",id},{"name",cell(sequences,r,1)},{"stages",list}});
   if(!screenId.isEmpty()){bool found=false;for(int i=0;i<screens.size();++i){auto s=screens[i].toObject();if(s.value("id")!=screenId)continue;found=true;auto elements=s.value("elements").toArray();const QString bid="direction-"+id;bool exists=false;for(int j=0;j<elements.size();++j){auto e=elements[j].toObject();if(e.value("id")==bid){e["action"]="playSequence";e["sequenceId"]=id;elements[j]=e;exists=true;}}if(!exists)elements.append(QJsonObject{{"id",bid},{"kind","button"},{"x",40},{"y",540+r*56},{"width",300},{"height",48},{"text",cell(sequences,r,1)},{"fill","#355c4c"},{"color","#ffffff"},{"action","playSequence"},{"sequenceId",id}});s["elements"]=elements;screens[i]=s;}if(!found)throw QString(tr("버튼을 배치할 화면 ID가 없습니다."));}
  }
  for(int j=0;j<cues->rowCount();++j)if(!sequenceIds.contains(cell(cues,j,0)))throw QString(tr("구간에 지정한 연출 ID가 없습니다."));if(as.isEmpty()||ss.isEmpty())throw QString(tr("배우와 연출을 하나 이상 만드세요."));visual["direction"]=QJsonObject{{"actors",as},{"sequences",ss}};visual["screens"]=screens;project["visual"]=visual;dialog.accept();
 }catch(const QString& m){error->setText(m);}});if(dialog.exec()==QDialog::Accepted)replaceProject(project);
}
